// === Tab: mySketch.js ===
// from "Falling drop of water" BY comado.

function setup() {
	createCanvas(4/3*windowHeight, windowHeight, WEBGL);
	angleMode(DEGREES);
	colorMode(HSB);
	strokeWeight(2);
}

function draw() {

	background(0);
	rotateX(80);
	blendMode(SCREEN);
	noFill()

	for(i = 0; i < 30; i++) {
		stroke(i*12, 100, 100)
		beginShape()

		for(j = 0; j <= 360; j+= 1) {
		  r = i * 4;
		  x = 3 * r * cos(j * 1);
		  y = 3 * r * sin(j * 1);
		  z = - r * tan( 3 * i + 1.5 * frameCount);
		  vertex(x, y, z);

		}
		endShape();
	}

}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +      ".jpg");
    lapse = millis();
  }
}

